messages.content:
Write the application service of PayOrder.

Design:
{
 "context": "orderpayments",
 "base_package": "com.bank.orderpayments",
 "entities": [
  {
   "name": "PaymentOrder",
   "table": "payment_order",
   "legacy_table": "db_pagos..pg_orden",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ord_numero"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ord_empresa"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ord_estado"
    },
    {
     "name": "paymentDate",
     "type": "timestamp(local)",
     "column": "payment_date",
     "legacy": "ord_fecha_pago"
    },
    {
     "name": "commission",
     "type": "decimal(19,4,signed)",
     "column": "commission",
     "legacy": "ord_comision"
    }
   ]
  },
  {
   "name": "CompanyTariff",
   "table": "company_tariff",
   "legacy_table": "db_admin..ad_tarifa_empresa",
   "key": [
    "companyId",
    "serviceCode"
   ],
   "fields": [
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "tar_empresa"
    },
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": "service_code",
     "legacy": "tar_servicio"
    },
    {
     "name": "tariffValue",
     "type": "decimal(19,4,signed)",
     "column": "tariff_value",
     "legacy": "tar_valor"
    },
    {
     "name": "separate",
     "type": "text(fixed,1,iso8859-1)",
     "column": "separate",
     "legacy": "tar_separada"
    }
   ]
  },
  {
   "name": "ServiceCatalog",
   "table": "service_catalog",
   "legacy_table": "db_admin..ad_servicio",
   "key": [
    "serviceCode"
   ],
   "fields": [
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": "service_code",
     "legacy": "srv_codigo"
    },
    {
     "name": "defaultTariff",
     "type": "decimal(19,4,signed)",
     "column": "default_tariff",
     "legacy": "srv_tarifa"
    }
   ]
  },
  {
   "name": "Account",
   "table": "account",
   "legacy_table": "db_cuentas..ct_cuenta",
   "key": [
    "accountNumber",
    "accountType"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": "account_number",
     "legacy": "cta_numero"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "cta_tipo"
    },
    {
     "name": "balance",
     "type": "decimal(19,4,signed)",
     "column": "balance",
     "legacy": "cta_saldo"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "PaymentOrder",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberAndCompany",
     "description": "Reads the order by number and company. Empty when it does not exist.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_orden"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets status 'A', payment date and commission on the order. Returns the number of rows updated.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_orden"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      },
      {
       "name": "paymentDate",
       "type": "timestamp(local)",
       "column": null,
       "legacy": "@i_fecha_proceso"
      },
      {
       "name": "commission",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@w_comision"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "CompanyTariffRepository",
   "entity": "CompanyTariff",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByCompanyAndService",
     "description": "Reads the company-specific tariff for a service. Empty when the company has none.",
     "inputs": [
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      },
      {
       "name": "serviceCode",
       "type": "text(var,10,iso8859-1)",
       "column": null,
       "legacy": "@i_servicio"
      }
     ],
     "returns": "CompanyTariff",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "ServiceCatalogRepository",
   "entity": "ServiceCatalog",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByCode",
     "description": "Reads the service with its default tariff.",
     "inputs": [
      {
       "name": "serviceCode",
       "type": "text(var,10,iso8859-1)",
       "column": null,
       "legacy": "@i_servicio"
      }
     ],
     "returns": "ServiceCatalog",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberAndType",
     "description": "Reads the account with its balance. Empty when it does not exist.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo_cuenta"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "DebitGateway",
   "entity": null,
   "legacy_program": "db_cuentas..sp_debito",
   "methods": [
    {
     "name": "debit",
     "description": "Debits the account and returns the movement sequence number. A non-zero legacy return code or a failure is raised as DebitRejectedException.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo"
      },
      {
       "name": "amount",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@i_valor"
      },
      {
       "name": "reference",
       "type": "text(var,30,iso8859-1)",
       "column": null,
       "legacy": "@i_referencia"
      }
     ],
     "returns": "int",
     "legacy_output": "@o_secuencial"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Pays a pending order. It validates the account type and the order, resolves the tariff, calculates the commission and the total, checks funds, debits the account (and the commission when charged separately) and marks the order as paid, all in one transaction.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-006",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013",
    "RULE-014",
    "RULE-015"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_orden"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_empresa"
    },
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": null,
     "legacy": "@i_servicio"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_tipo_cuenta"
    },
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "@i_cuenta"
    },
    {
     "name": "amount",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "@i_valor"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_canal"
    },
    {
     "name": "processDate",
     "type": "timestamp(local)",
     "column": null,
     "legacy": "@i_fecha_proceso"
    }
   ],
   "outputs": [
    {
     "name": "movement",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@o_movimiento"
    },
    {
     "name": "message",
     "type": "text(var,120,iso8859-1)",
     "column": null,
     "legacy": "@o_mensaje"
    }
   ],
   "errors": [
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "50001",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "50002",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "50003",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "50004",
     "message": "FONDOS INSUFICIENTES"
    },
    {
     "code": "DEBIT_FAILED",
     "legacy_code": "50005",
     "message": "ERROR EN DEBITO"
    },
    {
     "code": "COMMISSION_DEBIT_FAILED",
     "legacy_code": "50006",
     "message": "ERROR EN COMISION"
    },
    {
     "code": "ORDER_UPDATE_FAILED",
     "legacy_code": "50007",
     "message": "ERROR ACTUALIZANDO ORDEN"
    }
   ],
   "ports": [
    "OrderRepository",
    "CompanyTariffRepository",
    "ServiceCatalogRepository",
    "AccountRepository",
    "DebitGateway"
   ],
   "http_method": "POST",
   "path": "/payment-orders/payments",
   "legacy_program": "dbo.sp_pago_orden",
   "legacy_message": "@o_mensaje"
  }
 ],
 "decisions": [
  {
   "title": "One transaction for debit, commission and order update",
   "context": "The legacy opens a transaction (begin tran) after the funds check and rolls back explicitly on each failure (debit, commission, order update), committing at the end.",
   "decision": "PayOrder runs in a single @Transactional boundary starting before the first debit. Each failure raises the business exception for its code and the framework rolls back. The commit happens when the use case returns 'PAGO REALIZADO'. The validations before the debit (RULE-001 to RULE-008) are read-only and keep the legacy order.",
   "consequences": "The debit gateway must take part in the same transaction (same database or shared transaction manager), as sp_debito does in the legacy. If it is moved to a remote system, a compensation mechanism has to be designed separately."
  },
  {
   "title": "Debit failure is signalled by exception",
   "context": "sp_debito returns a code and the caller checks it (or @@error) for non-zero.",
   "decision": "DebitGateway.debit returns the movement sequence and raises DebitRejectedException on any non-zero code or failure. The use case maps it to DEBIT_FAILED (50005) for the payment debit and to COMMISSION_DEBIT_FAILED (50006) for the separate commission debit.",
   "consequences": "The numeric return codes and @@error checks are not translated. The sequence of the commission debit is discarded, as in the legacy."
  },
  {
   "title": "Money arithmetic and rounding",
   "context": "The legacy works with money (4 decimals) and uses round(tarifa/2, 2) for the WEB channel.",
   "decision": "All amounts are BigDecimal with scale 4. The WEB commission is tariff/2 rounded to 2 decimals with HALF_UP (1.25 gives 0.63), then stored at scale 4. NOMINA is applied last and forces commission 0.",
   "consequences": "Results match the golden master for amounts in the rules' scenarios. Edge cases of Sybase money division on odd 4th decimals must be confirmed in the replay."
  },
  {
   "title": "Tariff resolution and null handling",
   "context": "The company tariff is read first. Without a row, the service default is used. A null tariff becomes 0. When neither row exists the legacy leaves the 'separada' flag null.",
   "decision": "With a company row: tariff = tariffValue and separate = its flag. Without one: tariff = defaultTariff (0 if the service is missing or null) and separate = 'N'. A null tariff becomes 0. Only the exact value 'S' means separate charge.",
   "consequences": "A null flag and 'N' behave the same, as in the legacy."
  },
  {
   "title": "Missing account does not reject by itself",
   "context": "In the legacy a missing account leaves @w_saldo null, so the funds comparison is not true and the flow continues to sp_debito.",
   "decision": "If AccountRepository returns empty, the funds check (INSUFFICIENT_FUNDS) is skipped and the debit is attempted, so the gateway decides (DEBIT_FAILED). No new error code is created.",
   "consequences": "Behaviour is preserved on purpose. Adding an ACCOUNT_NOT_FOUND error would be a business change to approve separately."
  },
  {
   "title": "Funds rule and overdraft margin",
   "context": "VIR accounts must cover the total. Other types may go 100.00 below zero.",
   "decision": "Reject with INSUFFICIENT_FUNDS when (type = VIR and balance < total) or (type <> VIR and balance + 100.00 < total). The 100.00 margin is a constant of the use case.",
   "consequences": "The margin is not configurable until the business asks for it."
  },
  {
   "title": "Order update does not re-check the status",
   "context": "The legacy reads the status without locking, and the update filters only by order number and company.",
   "decision": "markPaid keeps the same filter and the use case treats 0 rows as ORDER_UPDATE_FAILED (50007). No locking or status condition is added.",
   "consequences": "The race between concurrent payments of the same order is the same as in the legacy. Optimistic locking can be added later as a deliberate change."
  },
  {
   "title": "Channel default and error plumbing",
   "context": "@i_canal defaults to 'WEB'. The legacy ends failures in cobis..sp_cerror and returns the error code.",
   "decision": "A missing channel is read as 'WEB'. sp_cerror is not translated: business exceptions are mapped by the framework to an HTTP error with the stable code and message. The success message is 'PAGO REALIZADO'.",
   "consequences": "Logging through sp_cerror is replaced by application logging."
  }
 ],
 "masks": [
  {
   "path": "outputs:@o_movimiento",
   "when": "rejected",
   "reason": "When the commission debit or the order update fails after the first debit, the legacy leaves the sequence of the rolled-back debit in @o_movimiento. The target returns no movement on a rejection because the transaction was rolled back and the movement does not exist."
  }
 ],
 "infrastructure": [
  "cobis..sp_cerror"
 ]
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Permitted account types for order payment",
  "category": "validation",
  "priority": "P0",
  "statement": "An order payment is only accepted for account types 'CTE', 'AHO' or 'VIR'. Any other account type is rejected with error 50001 and the message 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "@i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')",
  "action": "Set @w_error = 50001 and @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'.",
  "inputs": [
   {
    "name": "@i_tipo_cuenta",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type is permitted\n  Given @i_tipo_cuenta is 'AHO'\n  When the payment order is validated\n  Then no error is raised for the account type",
   "Scenario: Account type is not permitted\n  Given @i_tipo_cuenta is 'PRE'\n  When the payment order is validated\n  Then @w_error is 50001 and @o_mensaje is 'TIPO DE CUENTA NO PERMITIDO'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 34,
    "line_end": 37
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Only pending orders can be paid",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment order can only be processed if its status is 'P' (pending). If the order is in any other status, it is rejected with error 50003 and the message 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "ord_estado of the order (ord_numero = @i_orden, ord_empresa = @i_empresa) in db_pagos..pg_orden <> 'P'",
  "action": "Set @w_error = 50003 and @o_mensaje = 'ORDEN NO ESTA PENDIENTE'.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   },
   {
    "name": "@i_orden",
    "type": "text(fixed,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "ord_estado",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Pending order passes the check\n  Given order 'ORD0000001' of company 'E01' has status 'P'\n  When the payment of the order is requested\n  Then no error 50003 is raised and processing may continue",
   "Scenario: Non-pending order is rejected\n  Given order 'ORD0000001' of company 'E01' has status 'C'\n  When the payment of the order is requested\n  Then error 50003 is set\n  And the message is 'ORDEN NO ESTA PENDIENTE'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 42,
    "line_end": 45
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 54,
    "line_end": 57
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Payment requires an existing order",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment cannot be processed for an order that does not exist. When the order lookup returns no rows, the procedure reports error 50002 with the message 'ORDEN NO EXISTE'.",
  "condition": "The preceding query (not shown in this slice) affected or returned zero rows (@@rowcount = 0).",
  "action": "Set @w_error = 50002 and @o_mensaje = 'ORDEN NO EXISTE'.",
  "inputs": [
   {
    "name": "@@rowcount",
    "type": "integer(32,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n  Given the order lookup for the payment returns no rows\n  When the payment procedure evaluates the result\n  Then the error code is 50002\n  And the message is 'ORDEN NO EXISTE'",
   "Scenario: Order found\n  Given the order lookup returns one row\n  When the payment procedure evaluates the result\n  Then error 50002 is not raised by this check"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 47,
    "line_end": 50
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Company-specific service tariff with default fallback",
  "category": "calculation",
  "priority": "P0",
  "statement": "The service tariff is taken from the company-specific tariff for the service, together with its 'charged separately' flag. If the company has no specific tariff, the service's default tariff applies and the commission is never charged separately ('N'). A missing tariff is treated as 0.",
  "condition": "A row exists in ad_tarifa_empresa for tar_empresa = @i_empresa and tar_servicio = @i_servicio; otherwise (@@rowcount = 0) use ad_servicio where srv_codigo = @i_servicio; if the resulting tariff is null.",
  "action": "With a company row: tariff = tar_valor and separada = tar_separada. Without one: tariff = srv_tarifa and separada = 'N'. If the tariff is still null, tariff = 0.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_servicio",
    "type": "text(var,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "tar_valor",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "tar_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   },
   {
    "name": "srv_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "@w_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Company-specific tariff\n Given company 15 has a tariff of 2.00 for service 'LUZ' with separada 'S'\n When the payment is processed\n Then the tariff is 2.00 and separada is 'S'",
   "Scenario: Fallback to the service default\n Given company 15 has no tariff row for service 'AGUA' and the service default tariff is 1.50\n When the payment is processed\n Then the tariff is 1.50 and separada is 'N'",
   "Scenario: Missing tariff\n Given the tariff found is null\n When the payment is processed\n Then the tariff is 0"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 62,
    "line_end": 66
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 68,
    "line_end": 68
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 70,
    "line_end": 72
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 76,
    "line_end": 77
   }
  ]
 },
 {
  "id": "RULE-005",
  "name": "Missing tariff defaults to zero",
  "category": "calculation",
  "priority": "P0",
  "statement": "If no tariff value can be determined (NULL), the tariff is taken as 0, so no fee is charged.",
  "condition": "@w_tarifa is null after the lookup",
  "action": "@w_tarifa = 0",
  "inputs": [
   {
