    private static RuntimeException debitRejected() {
        String[] packages = {
            "com.bank.orderpayments.domain.error.",
            "com.bank.orderpayments.domain.exception.",
            "com.bank.orderpayments.domain.port.",
            "com.bank.orderpayments.application.",
            "com.bank.orderpayments.domain."
        };
        for (String pkg : packages) {
            Class<?> type;
            try {
                type = Class.forName(pkg + "DebitRejectedException");
            } catch (ClassNotFoundException e) {
                continue;
            }
            for (Constructor<?> constructor : type.getConstructors()) {
                Class<?>[] params = constructor.getParameterTypes();
                try {
                    Object instance;
                    if (params.length == 0) {
                        instance = constructor.newInstance();
                    } else if (params.length == 1 && params[0] == String.class) {
                        instance = constructor.newInstance("debit rejected");
                    } else if (params.length == 1 && params[0] == int.class) {
                        instance = constructor.newInstance(1);
                    } else if (params.length == 1 && params[0] == Throwable.class) {
                        instance = constructor.newInstance(new RuntimeException("debit rejected"));
                    } else {
                        continue;
                    }
                    if (instance instanceof RuntimeException runtime) {
                        return runtime;
                    }
                } catch (ReflectiveOperationException e) {
                    // try next constructor
                }
            }
        }
        throw new IllegalStateException("DebitRejectedException could not be instantiated");
    }

