        this.debitGateway = debitGateway;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        String channel = request.channel() == null ? "WEB" : request.channel();

        // RULE-001
        String accountType = request.accountType();
        if (!("CTE".equals(accountType) || "AHO".equals(accountType) || "VIR".equals(accountType))) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003 / RULE-002
        Optional<PaymentOrder> order = orderRepository.findByNumberAndCompany(
                request.orderNumber(), request.companyId());
        if (order.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }
        if (!"P".equals(order.get().status())) {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004 / RULE-005
        BigDecimal tariff;
        String separate;
        Optional<CompanyTariff> companyTariff = companyTariffRepository.findByCompanyAndService(
                request.companyId(), request.serviceCode());
        if (companyTariff.isPresent()) {
            tariff = companyTariff.get().tariffValue();
            separate = companyTariff.get().separate();
        } else {
            Optional<ServiceCatalog> catalog = serviceCatalogRepository.findByCode(request.serviceCode());
            tariff = catalog.map(ServiceCatalog::defaultTariff).orElse(null);
            separate = "N";
        }
        if (tariff == null) {
            tariff = BigDecimal.ZERO;
        }
        tariff = tariff.setScale(MONEY_SCALE, RoundingMode.HALF_UP);

        // RULE-006
        BigDecimal commission;
        if ("WEB".equals(channel)) {
            commission = tariff.divide(TWO, tariff.scale() + 1, RoundingMode.HALF_UP)
                    .setScale(2, RoundingMode.HALF_UP);
        } else {
            commission = tariff;
        }
        if ("NOMINA".equals(request.serviceCode())) {
            commission = BigDecimal.ZERO;
        }
        commission = commission.setScale(MONEY_SCALE, RoundingMode.HALF_UP);

        // RULE-007
        boolean separateCharge = "S".equals(separate);
        BigDecimal amount = request.amount();
        BigDecimal total = separateCharge ? amount : amount.add(commission);

        // RULE-008 (a missing account skips the check)
        Optional<Account> account = accountRepository.findByNumberAndType(
                request.accountNumber(), accountType);
        if (account.isPresent() && account.get().balance() != null) {
            BigDecimal balance = account.get().balance();
            boolean insufficient = "VIR".equals(accountType)
                    ? balance.compareTo(total) < 0
                    : balance.add(OVERDRAFT_MARGIN).compareTo(total) < 0;
            if (insufficient) {
                throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
            }
        }

        // RULE-009
        int movement;
        try {
            movement = debitGateway.debit(request.accountNumber(), accountType, total, "PAGO ORDEN");
        } catch (RuntimeException e) {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        // RULE-010 / RULE-011
        if (separateCharge && commission.compareTo(BigDecimal.ZERO) > 0) {
            try {
                debitGateway.debit(request.accountNumber(), accountType, commission, "COMISION PAGO");
            } catch (RuntimeException e) {
                throw new BusinessError("COMMISSION_DEBIT_FAILED", "50006", "ERROR EN COMISION");
            }
        }

        // RULE-012 / RULE-013 / RULE-014
        int rows = orderRepository.markPaid(request.orderNumber(), request.companyId(),
                request.processDate(), commission);
        if (rows == 0) {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        // RULE-015
        return new PayOrderResponse(movement, "PAGO REALIZADO");
    }
}
